{"command":"python3 - <<'PY'
import openpyxl, sys
from openpyxl.utils import get_column_letter
path='/root/output/result.xlsx'
wb=openpyxl.load_workbook(path,data_only=False)
ws=wb['Task']
print('Verification sample formulas:')
for addr in ['H12','L17','H26','L31','H35','L40','H42','H47','H50','L50']:
    v=ws[addr].value
    print(f'{addr}: {v!r}')
    if v is None:
        raise SystemExit(f'{addr} is None')
    if not (isinstance(v,str) and v.startswith('=')):
        raise SystemExit(f'{addr} is not a formula: {v!r}')
# Verify all target cells non-empty formulas
ranges=[]
for rs,re in [(12,17),(19,24),(26,31),(35,40),(42,47),(50,50)]:
    for r in range(rs,re+1):
        for c in range(8,13):
            ranges.append((r,c))
missing=[]; nonformula=[]
for r,c in ranges:
    v=ws.cell(r,c).value
    addr=f'{get_column_letter(c)}{r}'
    if v is None:
        missing.append(addr)
    elif not (isinstance(v,str) and v.startswith('=')):
        nonformula.append((addr,v))
print(f'Checked {len(ranges)} target cells.')
print('Missing:', missing)
print('Non-formulas:', nonformula[:10])
if missing or nonformula:
    raise SystemExit('Verification failed')
# Check percentile prefix survival
for addr in ['H46','L46','H47','L47']:
    v=ws[addr].value
    print(f'{addr}: {v!r}')
    if '_xlfn.PERCENTILE.INC' not in v:
        raise SystemExit(f'Percentile prefix missing at {addr}: {v!r}')
print('Workbook formula verification passed.')
